  (5, 'RETIRE', 'BIB Smart Retire', 'Guaranteed retirement income with savings protection.', 'An annuity plan that builds your retirement fund and pays a guaranteed annual income from your chosen retirement age until age 85, with a death benefit before retirement. Premiums may qualify for personal income tax deductions.', 'Retirement', 'product/bib_smart_retire.svg', 0, 1, TIMESTAMP(DATE_ADD(CURDATE(), INTERVAL -500 DAY), '10:00:00'));

